class ErrorBoundary extends Component<{children:ReactNode},{error:string}> {
  state={error:''}; static getDerivedStateFromError(error:Error){return {error:error.message||'Unexpected application error'};}
  render(){return this.state.error?<main className="card"><h1>CashFlow could not continue</h1><p className="error">{this.state.error}</p></main>:this.props.children;}
}
function Language({language,setLanguage}:{language:Lang;setLanguage:(v:Lang)=>void}) { return <select className="language" aria-label="Language" value={language} onChange={e=>setLanguage(e.target.value as Lang)}><option value="es">ES</option><option value="en">EN</option></select>; }
function Brand(){return <div className="brand"><img src={cashflowMark} alt="CashFlow"/><div><strong>CashFlow</strong><span>Control your money, clearly.</span></div></div>;}
function RuntimeMeta(){const [meta,setMeta]=useState({version:APP_VERSION,mode:window.cashflow?'Desktop · Local SQLite':'Web development · Local SQLite'});useEffect(()=>{window.cashflow?.runtime?.().then(value=>setMeta({version:value.version,mode:value.mode}));},[]);return <p className="runtime-meta">v{meta.version} · {meta.mode}</p>;}
function App(){
  const [language,setLanguage]=useState<Lang>('es'), [initialized,setInitialized]=useState<boolean|null>(null), [token,setToken]=useState(''), [user,setUser]=useState<User|null>(null), [recovery,setRecovery]=useState(''), [error,setError]=useState('');
  const t=copy[language];
  useEffect(()=>{request<{initialized:boolean}>('/v1/setup').then(v=>setInitialized(v.initialized)).catch(e=>setError(e.message));},[]);
  if(error)return <main><h1>CashFlow</h1><p className="error">{error}</p></main>;
  if(initialized===null)return <main>{t.loading}</main>;
  if(recovery)return <main className="card"><Language language={language} setLanguage={setLanguage}/><h1>{t.recovery}</h1><p>{t.recoveryHelp}</p><code>{recovery}</code><button onClick={()=>{setRecovery('');setInitialized(true);}}>{t.saved}</button></main>;
  if(!initialized)return <Setup t={t} language={language} setLanguage={setLanguage} done={setRecovery}/>;
  if(!token||!user)return <Login t={t} language={language} setLanguage={setLanguage} success={(nextToken,nextUser)=>{setToken(nextToken);setUser(nextUser);}}/>;
  return <Dashboard token={token} user={user} language={language} setLanguage={setLanguage} logout={()=>{request('/v1/auth/logout',token,'POST').finally(()=>{setToken('');setUser(null);});}}/>;
}
function Setup({t,language,setLanguage,done}:{t:Copy;language:Lang;setLanguage:(v:Lang)=>void;done:(v:string)=>void}){
  const [email,setEmail]=useState(''),[name,setName]=useState(''),[password,setPassword]=useState(''),[error,setError]=useState('');
  const submit=async(e:FormEvent)=>{e.preventDefault();try{const r=await request<{recovery_code:string}>('/v1/setup/initialize',undefined,'POST',{email,displayName:name,password});done(r.recovery_code);}catch(x){setError((x as Error).message);}};
  return <main className="auth-shell"><section className="auth-card"><div className="auth-topbar"><Language language={language} setLanguage={setLanguage}/><RuntimeMeta/></div><Brand/><h1>{t.setup}</h1><p>Storage: Local SQLite</p><form onSubmit={submit}><input placeholder={t.email} value={email} onChange={e=>setEmail(e.target.value)} required/><input placeholder={t.name} value={name} onChange={e=>setName(e.target.value)} required/><input type="password" placeholder="Password (12+ characters)" value={password} onChange={e=>setPassword(e.target.value)} required/><button>Create administrator</button>{error&&<p className="error">{error}</p>}</form></section></main>;
}
function Login({t,language,setLanguage,success}:{t:Copy;language:Lang;setLanguage:(v:Lang)=>void;success:(token:string,user:User)=>void}){
  const [email,setEmail]=useState(''),[password,setPassword]=useState(''),[error,setError]=useState('');
  const submit=async(e:FormEvent)=>{e.preventDefault();try{const r=await request<{token:string;user:User}>('/v1/auth/login',undefined,'POST',{email,password});success(r.token,r.user);}catch(x){setError((x as Error).message);}};
  return <main className="auth-shell"><section className="auth-card"><div className="auth-topbar"><Language language={language} setLanguage={setLanguage}/><RuntimeMeta/></div><Brand/><div className="auth-copy"><h1>{language==='es'?'Bienvenido nuevamente':'Welcome back'}</h1><p>{language==='es'?'Ingresá para continuar administrando tu flujo de caja.':'Sign in to continue managing your cash flow.'}</p></div><form onSubmit={submit}><input placeholder={t.email} value={email} onChange={e=>setEmail(e.target.value)} required/><input type="password" placeholder={t.password} value={password} onChange={e=>setPassword(e.target.value)} required/><button>{t.signIn}</button>{error&&<p className="error">{error}</p>}</form></section></main>;
}
function Amount({amount,currency,hidden}:{amount:number;currency?:string;hidden:boolean}){return <>{hidden?'•••••':(amount/100).toFixed(2)}{currency ? ` ${currency}` : ''}</>;}
function currentLocalDate(){const now=new Date();return `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;}
function formatAmount(value:string){const cleaned=value.replace(/[^\d,]/g,'');const [rawWhole,...rawDecimals]=cleaned.split(',');if(!rawWhole&&!rawDecimals.length)return '';const whole=(rawWhole||'0').replace(/^0+(?=\d)/,'');const grouped=whole.replace(/\B(?=(\d{3})+(?!\d))/g,'.');return rawDecimals.length?`${grouped},${rawDecimals.join('').slice(0,2)}`:grouped;}
function MoneyInput({placeholder}:{placeholder:string}){const [display,setDisplay]=useState('');return <><input className="money-value" aria-label={placeholder} inputMode="decimal" placeholder="$0,00" value={display ? `$${display}` : ''} onChange={e=>setDisplay(formatAmount(e.target.value))} required/><input name="amount" type="hidden" value={display.replace(/\./g,'').replace(',','.')} /></>;}
function downloadCSV(name:string, content:string){const url=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8'}));const anchor=document.createElement('a');anchor.href=url;anchor.download=name;anchor.click();URL.revokeObjectURL(url);}
function exportTimestamp(){const now=new Date();return `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}_${String(now.getHours()).padStart(2,'0')}-${String(now.getMinutes()).padStart(2,'0')}-${String(now.getSeconds()).padStart(2,'0')}`;}
const categoryTemplateCSV='name,direction\nOffice supplies,expense\n';
const movementTemplateCSV='account_name,category_name,direction,amount_minor,currency,description,occurred_on\nCash,Office supplies,expense,125000,ARS,Printer supplies,2026-08-22\n';
function parseCSV(content:string, expected:string[]){const rows:string[][]=[];let row:string[]=[],cell='',quoted=false;for(let index=0;index<content.length;index+=1){const char=content[index],next=content[index+1];if(char==='"'&&quoted&&next==='"'){cell+='"';index+=1;}else if(char==='"'){quoted=!quoted;}else if(char===','&&!quoted){row.push(cell.trim());cell='';}else if((char==='\n'||char==='\r')&&!quoted){if(char==='\r'&&next==='\n')index+=1;row.push(cell.trim());if(row.some(value=>value!==''))rows.push(row);row=[];cell='';}else{cell+=char;}}if(cell||row.length){row.push(cell.trim());rows.push(row);}if(rows.length<2||rows[0].join(',')!==expected.join(','))throw new Error(`CSV must use: ${expected.join(',')}`);if(rows.slice(1).some(values=>values.length!==expected.length))throw new Error('CSV contains a row with an invalid number of columns.');return rows.slice(1);}
function filterMovements(movements: Movement[], query: string, jql: boolean) {
  const normalized = query.trim().toLowerCase();
  const haystack = (movement: Movement) => `${movement.description ?? ''} ${movement.categoryName ?? ''} ${movement.currency ?? ''} ${movement.direction ?? ''} ${movement.status ?? ''} ${movement.occurredOn ?? ''}`.toLowerCase();
  if (!normalized) return movements;
  if (!jql) return movements.filter(movement => haystack(movement).includes(normalized));
  const groups = normalized.split(/\s+or\s+/i);
  return movements.filter(movement => groups.some(group => {
    const terms = (group.match(/(?:\w+:)?"[^"]*"|\S+/g) ?? []).filter(term => term.toLowerCase() !== 'and');
    return terms.every(term => {
      const [field, ...parts] = term.split(':');
      const value = parts.join(':');
      if (!value) return haystack(movement).includes(field);
      const text = value.replace(/^"|"$/g, '').toLowerCase();
      if (field === 'type' || field === 'direction') return movement.direction === text;
      if (field === 'category') return (movement.categoryName ?? '').toLowerCase().includes(text);
      if (field === 'currency') return movement.currency?.toLowerCase() === text;
      if (field === 'status') return movement.status === text;
		if (field === 'date') return movement.occurredOn === text;
		if (field === 'month') return movement.occurredOn.startsWith(text);
      if (field === 'from') return movement.occurredOn >= text;
      if (field === 'to') return movement.occurredOn <= text;
      return haystack(movement).includes(term);
    });
  }));
}
type FilterPill = { id: string; field: string; label: string; query: string; connector: 'AND' | 'OR' };
function MovementFilterBuilder({movements,query,setQuery,language,t,resetKey,savedFilters,onSave,onRename,onDuplicate,onDelete}:{movements:Movement[];query:string;setQuery:(value:string)=>void;language:Lang;t:Copy;resetKey:number;savedFilters:SavedFilter[];onSave:(name:string,query:string)=>void;onRename:(filter:SavedFilter,name:string)=>void;onDuplicate:(filter:SavedFilter)=>void;onDelete:(id:string)=>void}) {
  const [pills,setPills]=useState<FilterPill[]>([]);
  const [connector,setConnector]=useState<'AND'|'OR'>('AND');
  const [menu,setMenu]=useState<string>('');
  const [exactDate,setExactDate]=useState('');
  const [month,setMonth]=useState('');
  const [from,setFrom]=useState('');
  const [to,setTo]=useState('');
  const [showText,setShowText]=useState(false);
  const expression=(values:FilterPill[])=>values.map((pill,index)=>`${index ? `${pill.connector} ` : ''}${pill.query}`).join(' ');
  const scopeFor=(field:string)=>filterMovements(movements,expression(pills.filter(pill=>pill.field!==field)),true);
  const unique=(field:'direction'|'categoryName'|'currency'|'status')=>[...new Set(scopeFor(field==='direction'?'type':field==='categoryName'?'category':field).map(item=>item[field]).filter(Boolean))].sort();
  const add=(field:string,label:string,value:string)=>{
    const queryValue=field==='category'?`category:"${value}"`:`${field}:${value}`;
    const next={id:`${field}:${value}:${Date.now()}`,field,label,query:queryValue,connector};
    setPills(current=>{
      let updated:FilterPill[];
      if(connector==='AND'){
        const index=current.findIndex(item=>item.field===field);
        if(index>=0){const copy=[...current];copy[index]={...next,connector:copy[index].connector};updated=copy;setQuery(expression(updated));return updated;}
      }
      if(current.some(item=>item.query===queryValue))return current;
      updated=[...current,next];setQuery(expression(updated));return updated;
    });
    setMenu('');
  };
  const addRange=()=>{if(!from||!to||from>to)return;const label=`${from} → ${to}`;const next={id:`range:${from}:${to}`,field:'range',label,query:`from:${from} AND to:${to}`,connector};setPills(current=>{const updated=[...current.filter(item=>item.field!=='range'),next];setQuery(expression(updated));return updated;});setFrom('');setTo('');};
  const remove=(id:string)=>setPills(current=>{const updated=current.filter(item=>item.id!==id);setQuery(expression(updated));return updated;});
  useEffect(()=>{setPills([]);setMenu('');},[resetKey]);
  const menuValues=(key:string)=>key==='type'?unique('direction').map(value=>({value,label:value==='income'?t.income:t.expense})):key==='category'?unique('categoryName').map(value=>({value,label:value})):key==='currency'?unique('currency').map(value=>({value,label:value})):unique('status').map(value=>({value,label:value==='active'?t.active:t.voided}));
  const title=(key:string)=>key==='type'?(language==='es'?'Tipo':'Type'):key==='category'?(language==='es'?'Categoría':'Category'):key==='currency'?t.currency:t.status;
  return <><div className="filter-pills" aria-label={language==='es'?'Filtros aplicados':'Applied filters'}>{pills.length?pills.map(pill=><span className="filter-pill" key={pill.id}>{pill.connector} · {pill.label}<button onClick={()=>remove(pill.id)} aria-label={`${language==='es'?'Quitar':'Remove'} ${pill.label}`}>×</button></span>):<span className="filter-empty">{language==='es'?'Elegí un filtro para comenzar.':'Choose a filter to begin.'}</span>}</div><div className="filter-assistant"><span>{language==='es'?'Construir consulta:':'Build query:'}</span>{(['AND','OR'] as const).map(value=><button key={value} disabled={!pills.length} className={`secondary ${connector===value?'selected':''}`} onClick={()=>setConnector(value)}>{value}</button>)}{['type','category','currency','status'].map(key=>{const options=menuValues(key);return <div className="filter-select" key={key}><button className="secondary" disabled={!options.length} onClick={()=>setMenu(menu===key?'':key)} aria-expanded={menu===key}>{title(key)} ▾</button>{menu===key&&<div className="filter-menu">{options.map(option=><button key={option.value} onClick={()=>add(key,`${title(key)}: ${option.label}`,option.value)}>{option.label}</button>)}</div>}</div>})}</div><div className="date-filter-row"><label>{language==='es'?'Fecha':'Date'}<input type="date" value={exactDate} onChange={event=>setExactDate(event.target.value)} onBlur={()=>{if(exactDate)add('date',`${language==='es'?'Fecha':'Date'}: ${exactDate}`,exactDate);}}/></label><label>{language==='es'?'Mes':'Month'}<input type="month" value={month} onChange={event=>setMonth(event.target.value)} onBlur={()=>{if(month)add('month',`${language==='es'?'Mes':'Month'}: ${month}`,month);}}/></label><label>{language==='es'?'Desde':'From'}<input type="date" value={from} onChange={event=>setFrom(event.target.value)}/></label><label>{language==='es'?'Hasta':'To'}<input type="date" value={to} onChange={event=>setTo(event.target.value)}/></label><button className="secondary" disabled={!from||!to||from>to} onClick={addRange}>{language==='es'?'Aplicar rango':'Apply range'}</button></div><div className="query-tools"><button className="secondary" onClick={()=>setShowText(value=>!value)}>{showText?(language==='es'?'Ocultar texto':'Hide text'):(language==='es'?'Ver texto de consulta':'Show query text')}</button><button className="secondary" disabled={!query} onClick={()=>navigator.clipboard?.writeText(query)}>{language==='es'?'Copiar consulta':'Copy query'}</button><button className="secondary" disabled={!query} onClick={()=>{const name=window.prompt(language==='es'?'Nombre del filtro':'Filter name');if(name?.trim())onSave(name,query);}}>{language==='es'?'Guardar filtro':'Save filter'}</button></div>{showText&&<textarea className="jql-filter" value={query} onChange={event=>{setPills([]);setQuery(event.target.value);}} placeholder="type:expense AND category:&quot;alquiler&quot;" aria-label={language==='es'?'Consulta avanzada':'Advanced query'}/>}<div className="saved-filters"><strong>{language==='es'?'Filtros guardados':'Saved filters'}</strong>{savedFilters.length?savedFilters.map(filter=><div key={filter.id}><button className="secondary" onClick={()=>{setPills([]);setQuery(filter.query);}}>{filter.name}</button><button className="secondary" onClick={()=>{const name=window.prompt(language==='es'?'Nuevo nombre':'New name',filter.name);if(name?.trim())onRename(filter,name);}}>{language==='es'?'Renombrar':'Rename'}</button><button className="secondary" onClick={()=>onDuplicate(filter)}>{language==='es'?'Duplicar':'Duplicate'}</button><button className="secondary" onClick={()=>onDelete(filter.id)}>{language==='es'?'Eliminar':'Delete'}</button></div>):<small>{language==='es'?'Todavía no hay filtros guardados.':'No saved filters yet.'}</small>}</div><small>{language==='es'?'Las opciones disponibles se calculan sobre los movimientos que aún cumplen los filtros aplicados.':'Available options are calculated from movements that still satisfy the applied filters.'}</small></>;
}
function Dashboard({token,user,language,setLanguage,logout}:{token:string;user:User;language:Lang;setLanguage:(v:Lang)=>void;logout:()=>void}){
  const t=copy[language], [tab,setTab]=useState<Tab>('record'),[accounts,setAccounts]=useState<Account[]>([]),[categories,setCategories]=useState<Category[]>([]),[movements,setMovements]=useState<Movement[]>([]),[users,setUsers]=useState<User[]>([]),[requests,setRequests]=useState<DeletionRequest[]>([]),[auditEvents,setAuditEvents]=useState<AuditEvent[]>([]),[savedFilters,setSavedFilters]=useState<SavedFilter[]>([]),[error,setError]=useState(''),[notice,setNotice]=useState(''),[hidden,setHidden]=useState(true),[movementQuery,setMovementQuery]=useState(''),[filterReset,setFilterReset]=useState(0),[jqlMode,setJqlMode]=useState(false),[voidReason,setVoidReason]=useState(''),[categoryReplacement,setCategoryReplacement]=useState(''),[accountReplacement,setAccountReplacement]=useState(''),[pendingAction,setPendingAction]=useState<{kind:'accounts'|'categories'|'transactions'|'users';id:string;action:'activate'|'deactivate'|'void'|'delete'}|null>(null);
  const load=async()=>{try{const elevated=user.role==='administrator'||user.role==='manager';const [a,c,m,filters]=await Promise.all([request<Account[]>(`/v1/accounts${elevated?'?include_inactive=true':''}`,token),request<Category[]>(`/v1/categories${elevated?'?include_inactive=true':''}`,token),request<Movement[]>('/v1/transactions',token),request<SavedFilter[]>('/v1/saved-filters',token)]);setAccounts(a??[]);setCategories(c??[]);setMovements(m??[]);setSavedFilters(filters??[]);setRequests(await request<DeletionRequest[]>('/v1/deletion-requests',token));if(user.role==='administrator')setUsers(await request<User[]>('/v1/users',token));if(elevated)setAuditEvents(await request<AuditEvent[]>('/v1/audit-events',token));}catch(e){setError((e as Error).message);}};
  useEffect(()=>{load();},[]);
  useEffect(()=>{if(!notice&&!error)return;const timer=window.setTimeout(()=>{setNotice('');setError('');},10_000);return()=>window.clearTimeout(timer);},[notice,error]);
  const post=(path:string,body:(f:FormData)=>unknown,message=t.savedNotice)=>async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=e.currentTarget;setError('');try{await request(path,token,'POST',body(new FormData(form)));form.reset();await load();setNotice(message);}catch(x){setError((x as Error).message);}};
  const edit=async(kind:'accounts'|'categories',item:Account|Category)=>{const name=window.prompt(language==='es'?'Nombre':'Name',item.name);if(!name?.trim())return;const current='type'in item?item.type:item.direction;const value=window.prompt(kind==='accounts'?'cash | bank | wallet':'income | expense | both',current);if(!value)return;try{await request(`/v1/${kind}/${item.id}`,token,'PUT',kind==='accounts'?{name,type:value}:{name,direction:value});await load();setNotice(t.savedNotice);}catch(x){setError((x as Error).message);}};
  const deactivate=(kind:'accounts'|'categories',id:string)=>setPendingAction({kind,id,action:'deactivate'});
  const requestVoid=(id:string)=>setPendingAction({kind:'transactions',id,action:'void'});
  const userAction=(id:string,action:'activate'|'deactivate'|'delete')=>setPendingAction({kind:'users',id,action});
  const accountAction=(id:string,action:'activate'|'deactivate'|'delete')=>setPendingAction({kind:'accounts',id,action});
  const categoryAction=(id:string,action:'activate'|'deactivate')=>setPendingAction({kind:'categories',id,action});
  const bulkAction=async(kind:'accounts'|'categories'|'users',ids:string[],action:'activate'|'deactivate')=>{try{if(!ids.length)return;await Promise.all(ids.map(id=>request(`/v1/${kind}/${id}/${action}`,token,'POST')));await load();setNotice(language==='es'?`${ids.length} elementos actualizados.`:`${ids.length} items updated.`);}catch(x){setError((x as Error).message);}};
  const confirmAction=async()=>{if(!pendingAction)return;try{const {kind,id,action}=pendingAction;if(kind==='transactions'){await request(`/v1/transactions/${id}/void`,token,'POST',{reason:voidReason});setNotice(user.role==='operator'?(language==='es'?'Solicitud de anulación enviada.':'Void request submitted.'):t.voidedNotice);setVoidReason('');}else if(kind==='users'||kind==='accounts'){await request(`/v1/${kind}/${id}${action==='activate'?'/activate':action==='deactivate'?'/deactivate':''}`,token,action==='delete'?'DELETE':'POST',kind==='accounts'&&action==='delete'?{replacementAccountId:accountReplacement}:undefined);setNotice(action==='delete'?(language==='es'?'Elemento eliminado.':'Item deleted.'):(action==='activate'?(language==='es'?'Elemento activado.':'Item activated.'):(language==='es'?'Elemento desactivado.':'Item deactivated.')));setAccountReplacement('');}else if(action==='activate'){await request(`/v1/categories/${id}/activate`,token,'POST');setNotice(language==='es'?'Elemento activado.':'Item activated.');}else{await request(`/v1/${kind}/${id}/deactivate`,token,'POST',{replacementCategoryId:categoryReplacement});setNotice(t.deactivatedNotice);setCategoryReplacement('');}await load();}catch(x){setError((x as Error).message);}finally{setPendingAction(null);}};
  const resolveRequest=async(id:string,decision:'approve'|'reject')=>{try{await request(`/v1/deletion-requests/${id}/${decision}`,token,'POST');await load();setNotice(t.savedNotice);}catch(x){setError((x as Error).message);}};
  const cancelRequest=async(id:string)=>{try{await request(`/v1/deletion-requests/${id}/cancel`,token,'POST');await load();setNotice(language==='es'?'Solicitud cancelada.':'Request cancelled.');}catch(x){setError((x as Error).message);}};
  const exportCSV=async(path:string,name:string)=>{try{downloadCSV(name,await request<string>(path,token));}catch(x){setError((x as Error).message);}};
  const importCategoriesCSV=async(file:File)=>{try{const rows=parseCSV(await file.text(),['name','direction']);for(const [name,direction] of rows)await request('/v1/categories',token,'POST',{name,direction});await load();setNotice(t.savedNotice);}catch(x){setError((x as Error).message);}};
  const importMovementsCSV=async(file:File)=>{try{const rows=parseCSV(await file.text(),['account_name','category_name','direction','amount_minor','currency','description','occurred_on']);const accountIDs=new Map(accounts.filter(item=>item.active).map(item=>[item.name,item.id]));const categoryIDs=new Map(categories.map(item=>[item.name,item.id]));for(const row of rows){const accountName=row[0];if(accountName&&!accountIDs.has(accountName)){try{await request('/v1/accounts',token,'POST',{name:accountName,type:'cash'});}catch(error){if(!(error instanceof Error)||!error.message.includes('UNIQUE constraint failed: accounts.name'))throw error;}accountIDs.set(accountName,'');}const direction=row[2];const categoryName=row[1];if(categoryName&&!categoryIDs.has(categoryName)){try{await request('/v1/categories',token,'POST',{name:categoryName,direction});}catch(error){if(!(error instanceof Error)||!error.message.includes('UNIQUE constraint failed: categories.name'))throw error;}categoryIDs.set(categoryName,'');}}const elevated=user.role==='administrator'||user.role==='manager';const [latestAccounts,latestCategories]=await Promise.all([request<Account[]>(`/v1/accounts${elevated?'?include_inactive=true':''}`,token),request<Category[]>('/v1/categories',token)]);latestAccounts.filter(item=>item.active).forEach(item=>accountIDs.set(item.name,item.id));latestCategories.forEach(item=>categoryIDs.set(item.name,item.id));const values=rows.map((row,index)=>{const amountMinor=Number(row[3]);if(!Number.isSafeInteger(amountMinor)||amountMinor<=0)throw new Error(`Row ${index+2}: amount_minor must be a positive integer.`);const accountId=accountIDs.get(row[0]);if(!accountId)throw new Error(`Row ${index+2}: account ${row[0]} is inactive or could not be created.`);const categoryId=row[1]?categoryIDs.get(row[1]):'';if(row[1]&&!categoryId)throw new Error(`Row ${index+2}: category ${row[1]} could not be created.`);return {accountId,categoryId,direction:row[2],amountMinor,currency:row[4].toUpperCase(),description:row[5],occurredOn:row[6]};});for(const value of values)await request('/v1/transactions',token,'POST',value);await load();setNotice(t.savedNotice);}catch(x){setError((x as Error).message);}};
  const saveFilter=async(name:string,query:string)=>{try{await request('/v1/saved-filters',token,'POST',{name,query});await load();setNotice(language==='es'?'Filtro guardado.':'Filter saved.');}catch(x){setError((x as Error).message);}};
  const renameFilter=async(filter:SavedFilter,name:string)=>{try{await request(`/v1/saved-filters/${filter.id}`,token,'PUT',{name,query:filter.query});await load();setNotice(t.savedNotice);}catch(x){setError((x as Error).message);}};
  const duplicateFilter=async(filter:SavedFilter)=>saveFilter(`${filter.name} (${language==='es'?'copia':'copy'})`,filter.query);
  const deleteFilter=async(id:string)=>{try{await request(`/v1/saved-filters/${id}`,token,'DELETE');await load();setNotice(language==='es'?'Filtro eliminado.':'Filter deleted.');}catch(x){setError((x as Error).message);}};
  const labels:Record<Tab,string>={record:t.record,movements:t.movements,accounts:t.accounts,categories:t.categories,analytics:t.analytics,users:language==='es'?'Usuarios':'Users',requests:language==='es'?'Solicitudes':'Requests',audit:language==='es'?'Auditoría':'Audit'};
  const availableTabs=(Object.keys(labels) as Tab[]).filter(k=>user.role!=='operator'||k==='record'||k==='movements'||k==='categories'||k==='requests').filter(k=>user.role==='administrator'||k!=='users').filter(k=>user.role!=='operator'||k!=='audit');
  const visibleMovements=useMemo(()=>filterMovements(movements,movementQuery,jqlMode),[movements,movementQuery,jqlMode]);
  return <main><header><div><h1>CashFlow</h1><small>{user.displayName} · {user.role}</small></div><div className="header-actions"><Language language={language} setLanguage={setLanguage}/><button onClick={logout}>{t.signOut}</button></div></header><nav className="tabs">{availableTabs.map(k=><button key={k} className={tab===k?'selected':''} onClick={()=>setTab(k)}>{labels[k]}</button>)}</nav>{error&&<p className="error">{error}</p>}{notice&&<p className="notice">{notice}</p>}
  {tab==='record'&&<section className="card record-card"><h2>{t.record}</h2><form className="transaction" onSubmit={post('/v1/transactions',f=>({accountId:f.get('accountId'),categoryId:f.get('categoryId'),direction:f.get('direction'),amountMinor:Math.round(Number(f.get('amount'))*100),currency:String(f.get('currency')).toUpperCase(),description:f.get('description'),occurredOn:f.get('occurredOn')}))}><select className="transaction-account" name="accountId" required><option value="">{t.accounts}</option>{accounts.filter(a=>a.active).map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select><select className="transaction-category" name="categoryId"><option value="">{t.categories}</option>{categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select><select className="transaction-direction" name="direction"><option value="expense">{t.expense}</option><option value="income">{t.income}</option></select><MoneyInput placeholder={t.amount}/><select className="transaction-currency" name="currency" defaultValue="ARS" aria-label={t.currency}><option value="ARS">ARS · Peso argentino</option><option value="USD">USD · US dollar</option><option value="EUR">EUR · Euro</option><option value="BRL">BRL · Real brasileño</option></select><input className="transaction-date" name="occurredOn" type="date" defaultValue={currentLocalDate()} aria-label={t.date} required/><input className="transaction-description" name="description" placeholder={t.description}/><button className="transaction-save">{t.save}</button></form></section>}
  {tab==='movements'&&<section className="card"><div className="section-head"><h2>{t.movements}</h2><button className="secondary" onClick={()=>setHidden(!hidden)}>◉ {hidden?t.show:t.hide}</button></div><div className="filter-mode"><button className={!jqlMode?'selected':''} onClick={()=>setJqlMode(false)}>{language==='es'?'Búsqueda normal':'Normal search'}</button><button className={jqlMode?'selected':''} onClick={()=>setJqlMode(true)}>{language==='es'?'Consulta avanzada':'Advanced query'}</button><button className="secondary" onClick={()=>{setMovementQuery('');setFilterReset(value=>value+1);}}>{language==='es'?'Limpiar':'Clear'}</button></div>{jqlMode?<MovementFilterBuilder key={filterReset} movements={movements} query={movementQuery} setQuery={setMovementQuery} language={language} t={t} resetKey={filterReset} savedFilters={savedFilters} onSave={saveFilter} onRename={renameFilter} onDuplicate={duplicateFilter} onDelete={deleteFilter}/>:<input className="movement-search" value={movementQuery} onChange={e=>setMovementQuery(e.target.value)} placeholder={language==='es'?'Buscar por descripción, categoría, moneda, tipo o estado':'Search description, category, currency, type, or status'}/>}<CsvActions onTemplate={()=>downloadCSV('cashflow-movements-template.csv',movementTemplateCSV)} onImport={importMovementsCSV} onExport={user.role==='operator'?undefined:()=>exportCSV('/v1/exports/transactions.csv',`cashflow-movements-${exportTimestamp()}.csv`)}/><table><thead><tr><th>{t.date}</th><th>{t.type}</th><th>{t.categories}</th><th>{t.currency}</th><th>{t.amount}</th><th>{t.description}</th><th>{t.status}</th><th/></tr></thead><tbody>{visibleMovements.map(m=><tr key={m.id} className={m.status==='voided'?'voided-row':''}><td>{m.occurredOn}</td><td>{m.direction==='income'?t.income:t.expense}</td><td>{m.categoryName||'—'}</td><td>{m.currency}</td><td><Amount amount={m.amountMinor} hidden={hidden}/></td><td>{m.description}</td><td>{m.status==='active'?t.active:t.voided}</td><td>{m.status==='active'&&<button className="secondary" onClick={()=>requestVoid(m.id)}>{user.role==='operator'?(language==='es'?'Solicitar anulación':'Request void'):t.void}</button>}</td></tr>)}</tbody></table></section>}
  {tab==='accounts'&&<Management t={t} kind="accounts" items={accounts} submit={post('/v1/accounts',f=>({name:f.get('name'),type:f.get('type')}))} edit={v=>edit('accounts',v)} deactivate={id=>deactivate('accounts',id)} onAccountAction={accountAction} onBulk={(ids,action)=>bulkAction('accounts',ids,action)}/>}
  {tab==='categories'&&user.role==='operator'&&<section className="card"><h2>{t.categories}</h2><form className="inline" onSubmit={post('/v1/categories',f=>({name:f.get('name'),direction:f.get('direction')}))}><input name="name" placeholder={t.categoryName} required/><select name="direction"><option value="expense">{t.expense}</option><option value="income">{t.income}</option><option value="both">Both</option></select><button>{t.add}</button></form></section>}
  {tab==='categories'&&user.role!=='operator'&&<Management t={t} kind="categories" items={categories} submit={post('/v1/categories',f=>({name:f.get('name'),direction:f.get('direction')}))} edit={v=>edit('categories',v)} deactivate={id=>deactivate('categories',id)} onCategoryAction={categoryAction} onBulk={(ids,action)=>bulkAction('categories',ids,action)} csv={{onTemplate:()=>downloadCSV('cashflow-categories-template.csv',categoryTemplateCSV),onImport:importCategoriesCSV}}/>}
  {tab==='analytics'&&<Analytics t={t} movements={movements} hidden={hidden}/>} 
  {tab==='users'&&user.role==='administrator'&&<UserManagement users={users} currentUserId={user.id} submit={post('/v1/users',f=>({email:f.get('email'),displayName:f.get('displayName'),password:f.get('password'),role:f.get('role')}))} onAction={userAction} onBulk={(ids,action)=>bulkAction('users',ids,action)} language={language}/>}
  {tab==='requests'&&<DeletionRequests requests={requests} resolve={resolveRequest} cancel={cancelRequest} canResolve={user.role!=='operator'} language={language}/>}
  {tab==='audit'&&user.role!=='operator'&&<AuditTrail events={auditEvents} language={language}/>}
  {pendingAction&&<div className="modal-backdrop" role="presentation"><section className="modal" role="dialog" aria-modal="true" aria-labelledby="confirm-action-title"><h2 id="confirm-action-title">{pendingAction.action==='void'?(language==='es'?'¿Confirmar anulación?':'Confirm void?'):pendingAction.action==='delete'?(language==='es'?'¿Eliminar este elemento?':'Delete this item?'):pendingAction.action==='activate'?(language==='es'?'¿Activar este elemento?':'Activate this item?'):(language==='es'?'¿Desactivar este elemento?':'Deactivate this item?')}</h2><p>{pendingAction.action==='void'?(user.role==='operator'?(language==='es'?'Se creará una solicitud para que un administrador o gestor la apruebe.':'A request will be created for an administrator or manager to approve.'):(language==='es'?'El movimiento quedará anulado y se conservará en el historial.':'The movement will be voided and retained in history.')):pendingAction.action==='delete'?(language==='es'?'La eliminación es permanente. Si existen movimientos, elegí una cuenta destino para migrarlos.':'Deletion is permanent. If movements exist, choose a destination account to migrate them.'):(language==='es'?'Se actualizará el estado del elemento.':'The item status will be updated.')}</p>{pendingAction.action==='void'&&user.role==='operator'&&<textarea value={voidReason} onChange={e=>setVoidReason(e.target.value)} placeholder={language==='es'?'Motivo de la solicitud':'Request reason'} required/>}{pendingAction.kind==='categories'&&pendingAction.action==='deactivate'&&<label>{language==='es'?'Si la categoría tiene movimientos, migrarlos a:':'If the category has movements, migrate them to:'}<select value={categoryReplacement} onChange={e=>setCategoryReplacement(e.target.value)}><option value="">{language==='es'?'Seleccionar si corresponde':'Select if needed'}</option>{categories.filter(category=>category.active&&category.id!==pendingAction.id).map(category=><option key={category.id} value={category.id}>{category.name}</option>)}</select></label>}{pendingAction.kind==='accounts'&&pendingAction.action==='delete'&&<label>{language==='es'?'Si la cuenta tiene movimientos, migrarlos a:':'If the account has movements, migrate them to:'}<select value={accountReplacement} onChange={e=>setAccountReplacement(e.target.value)}><option value="">{language==='es'?'Seleccionar si corresponde':'Select if needed'}</option>{accounts.filter(account=>account.active&&account.id!==pendingAction.id).map(account=><option key={account.id} value={account.id}>{account.name}</option>)}</select></label>}<div className="modal-actions"><button className="secondary" onClick={()=>{setPendingAction(null);setVoidReason('');setCategoryReplacement('');setAccountReplacement('');}}>{language==='es'?'Cancelar':'Cancel'}</button><button disabled={pendingAction.action==='void'&&user.role==='operator'&&!voidReason.trim()} onClick={confirmAction}>{pendingAction.action==='void'?(language==='es'?'Confirmar':'Confirm'):pendingAction.action==='delete'?(language==='es'?'Eliminar':'Delete'):pendingAction.action==='activate'?(language==='es'?'Activar':'Activate'):(language==='es'?'Desactivar':'Deactivate')}</button></div></section></div>}
  </main>;
}
function CsvActions({onTemplate,onImport,onExport}:{onTemplate:()=>void;onImport:(file:File)=>void;onExport?:()=>void}){const selectFile=(event:ChangeEvent<HTMLInputElement>)=>{const file=event.target.files?.[0];if(file)onImport(file);event.target.value='';};return <div className="csv-actions"><button className="secondary" onClick={onTemplate}>Download template</button><label className="secondary file-action">Import CSV<input type="file" accept=".csv,text/csv" onChange={selectFile}/></label>{onExport&&<button className="secondary" onClick={onExport}>Export CSV</button>}</div>;}
function Management({t,kind,items,submit,edit,deactivate,csv,onAccountAction,onCategoryAction,onBulk}:{t:Copy;kind:'accounts'|'categories';items:(Account|Category)[];submit:(e:FormEvent<HTMLFormElement>)=>void;edit:(v:Account|Category)=>void;deactivate:(id:string)=>void;csv?:{onTemplate:()=>void;onImport:(file:File)=>void};onAccountAction?:(id:string,action:'activate'|'deactivate'|'delete')=>void;onCategoryAction?:(id:string,action:'activate'|'deactivate')=>void;onBulk?:(ids:string[],action:'activate'|'deactivate')=>void}) {
  const accounts = kind === 'accounts';
  const [selected,setSelected]=useState<string[]>([]),[usage,setUsage]=useState('all');
  const usageCount=(item:Account|Category)=>'usageCount' in item?item.usageCount:0;
  const shown=items.filter(item=>!accounts?(usage==='all'||(usage==='used'&&usageCount(item)>0)||(usage==='unused'&&usageCount(item)===0)):true);
  const toggle=(id:string)=>setSelected(current=>current.includes(id)?current.filter(value=>value!==id):[...current,id]);
  const bulk=(action:'activate'|'deactivate')=>{const ids=shown.filter(item=>selected.includes(item.id)&&item.active===(action==='deactivate')).filter(item=>accounts||usageCount(item)===0).map(item=>item.id);onBulk?.(ids,action);setSelected([]);};
  return <section className="card"><h2>{accounts ? t.accounts : t.categories}</h2><form className="inline" onSubmit={submit}><input name="name" placeholder={accounts ? t.accountName : t.categoryName} required/><select name={accounts ? 'type' : 'direction'}>{accounts ? <><option value="cash">Cash</option><option value="bank">Bank</option><option value="wallet">Wallet</option></> : <><option value="expense">{t.expense}</option><option value="income">{t.income}</option><option value="both">Both</option></>}</select><button>{t.add}</button></form>{csv&&<CsvActions {...csv}/>} {!accounts&&<div className="bulk-actions"><label>{t.active==='Activo'?'Uso':'Usage'} <select value={usage} onChange={event=>setUsage(event.target.value)}><option value="all">{t.active==='Activo'?'Todas':'All'}</option><option value="used">{t.active==='Activo'?'Con movimientos':'With movements'}</option><option value="unused">{t.active==='Activo'?'Sin movimientos':'Without movements'}</option></select></label></div>}<div className="bulk-actions"><button className="secondary" disabled={!selected.some(id=>items.find(item=>item.id===id)?.active===false)} onClick={()=>bulk('activate')}>{t.active==='Activo'?'Activar seleccionadas':'Activate selected'}</button><button className="secondary" disabled={!selected.some(id=>{const item=items.find(value=>value.id===id);return item?.active&&(accounts||item.usageCount===0);})} onClick={()=>bulk('deactivate')}>{t.active==='Activo'?'Desactivar seleccionadas':'Deactivate selected'}</button>{!accounts&&<small>{t.active==='Activo'?'Las categorías con movimientos se desactivan individualmente para elegir su migración.':'Categories with movements are deactivated individually to choose their migration.'}</small>}</div>{shown.length ? <ul className="management-list">{shown.map(item => <li key={item.id} className={item.active?'':'voided-row'}><input type="checkbox" checked={selected.includes(item.id)} onChange={()=>toggle(item.id)}/><span>{item.name} <small>{'type' in item ? item.type : item.direction} · {'usageCount' in item ? `${item.usageCount} ${t.active==='Activo'?'movimientos':'movements'} · ` : ''}{item.active?(t.active):'inactive'}</small></span><span>{item.active?<><button className="secondary" onClick={() => edit(item)}>{t.edit}</button><button className="secondary" onClick={() => accounts&&onAccountAction?onAccountAction(item.id,'deactivate'):onCategoryAction?.(item.id,'deactivate')}>{t.deactivate}</button></>:accounts&&onAccountAction?<><button className="secondary" onClick={()=>onAccountAction(item.id,'activate')}>{languageLabel(t,'activate')}</button><button className="secondary" onClick={()=>onAccountAction(item.id,'delete')}>{languageLabel(t,'delete')}</button></>:<button className="secondary" onClick={()=>onCategoryAction?.(item.id,'activate')}>{languageLabel(t,'activate')}</button>}</span></li>)}</ul> : <p className="items">{accounts ? t.noAccounts : t.noCategories}</p>}</section>;
}
function languageLabel(t:Copy, action:'activate'|'delete'){return action==='activate'?(t.active==='Activo'?'Activar':'Activate'):(t.active==='Activo'?'Eliminar':'Delete');}
function UserManagement({users,currentUserId,submit,onAction,onBulk,language}:{users:User[];currentUserId:string;submit:(event:FormEvent<HTMLFormElement>)=>void;onAction:(id:string,action:'activate'|'deactivate'|'delete')=>void;onBulk:(ids:string[],action:'activate'|'deactivate')=>void;language:Lang}){const [selected,setSelected]=useState<string[]>([]);const toggle=(id:string)=>setSelected(current=>current.includes(id)?current.filter(value=>value!==id):[...current,id]);const bulk=(action:'activate'|'deactivate')=>{onBulk(selected.filter(id=>users.find(user=>user.id===id)?.active===(action==='deactivate')),action);setSelected([]);};return <section className="card"><h2>{language==='es'?'Usuarios':'Users'}</h2><form className="inline" onSubmit={submit}><input name="displayName" placeholder={language==='es'?'Nombre':'Name'} required/><input name="email" type="email" placeholder="Email" required/><input name="password" type="password" placeholder={language==='es'?'Contraseña (12+ caracteres)':'Password (12+ characters)'} required/><select name="role"><option value="operator">{language==='es'?'Operador':'Operator'}</option><option value="manager">{language==='es'?'Gestor':'Manager'}</option><option value="administrator">{language==='es'?'Administrador':'Administrator'}</option></select><button>{language==='es'?'Crear usuario':'Create user'}</button></form><div className="bulk-actions"><button className="secondary" disabled={!selected.some(id=>users.find(user=>user.id===id)?.active===false)} onClick={()=>bulk('activate')}>{language==='es'?'Activar seleccionados':'Activate selected'}</button><button className="secondary" disabled={!selected.some(id=>users.find(user=>user.id===id)?.active===true)} onClick={()=>bulk('deactivate')}>{language==='es'?'Desactivar seleccionados':'Deactivate selected'}</button></div><ul className="management-list">{users.map(item=><li key={item.id} className={item.active?'':'voided-row'}>{item.id!==currentUserId&&<input type="checkbox" checked={selected.includes(item.id)} onChange={()=>toggle(item.id)}/>}<span>{item.displayName}<small> {item.email} · {item.role} · {item.active?(language==='es'?'activo':'active'):(language==='es'?'inactivo':'inactive')}</small></span>{item.id!==currentUserId&&<span>{item.active?<button className="secondary" onClick={()=>onAction(item.id,'deactivate')}>{language==='es'?'Desactivar':'Deactivate'}</button>:<button className="secondary" onClick={()=>onAction(item.id,'activate')}>{language==='es'?'Activar':'Activate'}</button>}<button className="secondary" onClick={()=>onAction(item.id,'delete')}>{language==='es'?'Eliminar':'Delete'}</button></span>}</li>)}</ul></section>;}
function DeletionRequests({requests,resolve,cancel,canResolve,language}:{requests:DeletionRequest[];resolve:(id:string,decision:'approve'|'reject')=>void;cancel:(id:string)=>void;canResolve:boolean;language:Lang}){const pending=requests.filter(item=>item.status==='pending'),completed=requests.filter(item=>item.status!=='pending');const list=(items:DeletionRequest[],actions:boolean)=><ul className="management-list">{items.map(item=><li key={item.id}><span><strong>{language==='es'?'Movimiento':'Movement'} </strong><small>{item.entityId} · {item.createdAt}</small><br/><small>{language==='es'?'Solicitante':'Requested by'}: {item.requestedByName} · {language==='es'?'Motivo':'Reason'}: {item.reason}</small>{item.resolvedAt&&<><br/><small>{language==='es'?'Tramitada':'Processed'}: {item.status} · {item.resolvedAt}</small></>}</span>{actions&&<span>{canResolve?<><button onClick={()=>resolve(item.id,'approve')}>{language==='es'?'Aprobar':'Approve'}</button><button className="secondary" onClick={()=>resolve(item.id,'reject')}>{language==='es'?'Rechazar':'Reject'}</button></>:<button className="secondary" onClick={()=>cancel(item.id)}>{language==='es'?'Cancelar solicitud':'Cancel request'}</button>}</span>}</li>)}</ul>;return <section className="card"><h2>{language==='es'?'Solicitudes de anulación':'Void requests'}</h2>{pending.length?list(pending,true):<p className="items">{language==='es'?'No hay solicitudes pendientes.':'No pending requests.'}</p>}{completed.length>0&&<details><summary>{language==='es'?`Tramitadas (${completed.length})`:`Processed (${completed.length})`}</summary>{list(completed,false)}</details>}</section>;}
function traceJSON(value:string){if(!value||value==='null')return '—';try{return JSON.stringify(JSON.parse(value),null,2);}catch{return value;}}
function AuditTrail({events,language}:{events:AuditEvent[];language:Lang}){const [search,setSearch]=useState('');const [entity,setEntity]=useState('');const [correlation,setCorrelation]=useState('');const entities=[...new Set(events.map(event=>event.entityType))].sort();const visible=events.filter(event=>{const text=`${event.action} ${event.actorName} ${event.entityType} ${event.entityId} ${event.correlationId}`.toLowerCase();return (!search||text.includes(search.toLowerCase()))&&(!entity||event.entityType===entity)&&(!correlation||event.correlationId===correlation);});return <section className="card audit-trail"><div className="section-head"><div><h2>{language==='es'?'Auditoría':'Audit trail'}</h2><p className="items">{language==='es'?'Trazabilidad inmutable de cada acción registrada.':'Immutable trace of every recorded action.'}</p></div><strong>{visible.length} / {events.length}</strong></div><div className="audit-filters"><input value={search} onChange={event=>setSearch(event.target.value)} placeholder={language==='es'?'Buscar por acción, usuario o ID…':'Search action, user or ID…'}/><select value={entity} onChange={event=>setEntity(event.target.value)}><option value="">{language==='es'?'Todas las entidades':'All entities'}</option>{entities.map(value=><option key={value} value={value}>{value}</option>)}</select><input value={correlation} onChange={event=>setCorrelation(event.target.value)} placeholder={language==='es'?'ID de correlación':'Correlation ID'}/></div>{visible.length?<ol className="audit-list">{visible.map(event=><li key={event.id}><details><summary><time>{new Date(event.createdAt).toLocaleString(language==='es'?'es-AR':'en-US')}</time><strong>{event.action.replaceAll('_',' ')}</strong><span>{event.actorName}</span><small>{event.entityType} · {event.entityId}</small></summary><div className="audit-details"><dl><dt>{language==='es'?'Actor':'Actor'}</dt><dd>{event.actorName} <code>{event.actorId||'system'}</code></dd><dt>{language==='es'?'Entidad':'Entity'}</dt><dd>{event.entityType} <code>{event.entityId}</code></dd><dt>{language==='es'?'Correlación':'Correlation'}</dt><dd><code>{event.correlationId}</code></dd><dt>{language==='es'?'Evento':'Event'}</dt><dd><code>{event.id}</code></dd></dl><div className="audit-payload"><section><h3>{language==='es'?'Antes':'Before'}</h3><pre>{traceJSON(event.before)}</pre></section><section><h3>{language==='es'?'Después':'After'}</h3><pre>{traceJSON(event.after)}</pre></section></div></div></details></li>)}</ol>:<p className="items">{language==='es'?'No hay eventos para esos filtros.':'No events match these filters.'}</p>}</section>;}
function Analytics({t,movements,hidden}:{t:Copy;movements:Movement[];hidden:boolean}){const [year,setYear]=useState(String(new Date().getFullYear()));const stats=useMemo(()=>{const data=new Map<string,{month:string;currency:string;income:number;expense:number}>();movements.filter(m=>m.status==='active'&&m.occurredOn.startsWith(year)).forEach(m=>{const key=`${m.occurredOn.slice(0,7)}-${m.currency}`,current=data.get(key)??{month:m.occurredOn.slice(0,7),currency:m.currency,income:0,expense:0};current[m.direction==='income'?'income':'expense']+=m.amountMinor;data.set(key,current);});return [...data.values()];},[movements,year]);if(!stats.length)return <section className="card"><div className="section-head"><h2>{t.analytics}</h2><label>{t.year} <input value={year} maxLength={4} onChange={e=>setYear(e.target.value)}/></label></div><p>{t.noData}</p></section>;const income=stats.reduce((a,b)=>a.income>b.income?a:b),expense=stats.reduce((a,b)=>a.expense>b.expense?a:b),averages=Object.entries(stats.reduce<Record<string,{total:number;months:number}>>((a,v)=>{const x=a[v.currency]??{total:0,months:0};x.total+=v.income;x.months++;a[v.currency]=x;return a;},{}));return <section className="card"><div className="section-head"><h2>{t.analytics}</h2><label>{t.year} <input value={year} maxLength={4} onChange={e=>setYear(e.target.value)}/></label></div><div className="summary"><strong>{t.topIncome}: {income.month} · <Amount amount={income.income} currency={income.currency} hidden={hidden}/></strong><strong>{t.topExpense}: {expense.month} · <Amount amount={expense.expense} currency={expense.currency} hidden={hidden}/></strong>{averages.map(([currency,v])=><strong key={currency}>{t.monthlyIncome} ({currency}): <Amount amount={Math.round(v.total/v.months)} currency={currency} hidden={hidden}/></strong>)}</div></section>;}
createRoot(document.getElementById('root')!).render(<ErrorBoundary><App/></ErrorBoundary>);
